+        SentMessages messages = new SentMessages(testConfig);
+
+        messages.add("EMAIL", "guest@example.com", "Reservation Confirmed", "Your booking details:\nRoom 201");
+
+        List<Message> all = messages.all();
+        assertEquals(1, all.size());
